trait Animal {
    fn speak(&self) -> String;
}

struct Dog;
struct Cat;

impl Animal for Dog {
    fn speak(&self) -> String { "woof".to_string() }
}

impl Animal for Cat {
    fn speak(&self) -> String { "meow".to_string() }
}

fn main() {
    let mut animals: Vec<Box<dyn Animal>> = Vec::new();
    animals.push(Box::new(Dog));
    animals.push(Box::new(Cat));
    for a in animals {
        println!("{}", a.speak());
    }
}
